function c(e,t=new Date){const n=new Date(e).getTime();if(Number.isNaN(n))return 0;const r=Math.floor((t.getTime()-n)/6e4);return r>0?r:0}function f(e){if(e<60)return`${e} min`;const t=Math.floor(e/60),n=e%60;return`${t} h ${String(n).padStart(2,"0")} min`}function u(e){return e>=60?"critica":e>=30?"atencao":"normal"}function a(e,t=new Date){const n=new Date(e).getTime();if(Number.isNaN(n))return 0;const r=Math.floor((t.getTime()-n)/864e5);return r>0?r:0}const i=30;function s(e,t,n=new Date,r=i){return["PENDENTE","ACEITO","ENVIADO","OFICIO_GERADO"].includes(e)?a(t,n)>r:!1}export{s as e,f,a as i,c as m,u};
